const double PI = 3.14159265358979323846;

struct Complex {
    double re, im;
    Complex(double r = 0, double i = 0) : re(r), im(i) {}
    Complex operator+(const Complex &o) const { return Complex(re + o.re, im + o.im); }
    Complex operator-(const Complex &o) const { return Complex(re - o.re, im - o.im); }
    Complex operator*(const Complex &o) const { 
        return Complex(re * o.re - im * o.im, re * o.im + im * o.re); 
    }
};

double sin_approx(double x) {
    while (x > PI) x -= 2 * PI;
    while (x < -PI) x += 2 * PI;
    double x3 = x * x * x;
    double x5 = x3 * x * x;
    double x7 = x5 * x * x;
    return x - x3 / 6.0 + x5 / 120.0 - x7 / 5040.0;
}

double cos_approx(double x) {
    while (x > PI) x -= 2 * PI;
    while (x < -PI) x += 2 * PI;
    double x2 = x * x;
    double x4 = x2 * x2;
    double x6 = x4 * x2;
    return 1 - x2 / 2.0 + x4 / 24.0 - x6 / 720.0;
}

void fft(Complex *a, int n) {
    if (n <= 1) return;
    Complex *even = new Complex[n/2];
    Complex *odd = new Complex[n/2];
    for (int i = 0; i < n/2; ++i) {
        even[i] = a[2*i];
        odd[i] = a[2*i + 1];
    }

    fft(even, n/2);
    fft(odd,  n/2);

    for (int k = 0; k < n/2; ++k) {
        double angle = -2 * PI * k / n;
        Complex w(cos_approx(angle), sin_approx(angle));
        Complex t = w * odd[k];
        a[k] = even[k] + t;
        a[k + n/2] = even[k] - t;
    }
    delete[] even;
    delete[] odd;
}

int main() {
    int n = 8;
    Complex data[8];
    for (int i = 0; i < n; ++i) {
        data[i] = Complex(i, 0);
    }

    fft(data, n);

    for (int i = 0; i < n; ++i) {
        cout << "FFT[" << i << "] = "
             << data[i].re << " + " << data[i].im << "i\n";
    }
    return 0;
}

#include <iostream>
using namespace std;

const int NUM_TRAIN = 6;
const int DIM = 3;
const int K = 3;

int knn(const double train[][DIM], const int labels[], int num_train, const double query_point[]) {
    double dist[NUM_TRAIN];
    int idx[NUM_TRAIN];

    for (int i = 0; i < num_train; i++) {
        double sum = 0.0;
        for (int d = 0; d < DIM; d++) {
            double diff = train[i][d] - query_point[d];
            sum += diff * diff;
        }
        dist[i] = sum;
        idx[i] = i;
    }

    for (int i = 0; i < K; i++) {
        int min_j = i;
        for (int j = i + 1; j < num_train; j++) {
            if (dist[j] < dist[min_j]) {
                min_j = j;
            }
        }
        double tmpDist = dist[i]; dist[i] = dist[min_j]; dist[min_j] = tmpDist;
        int tmpIdx = idx[i];   idx[i]   = idx[min_j];   idx[min_j]   = tmpIdx;
    }

    int count0 = 0, count1 = 0;
    for (int i = 0; i < K; i++) {
        int label = labels[idx[i]];
        if (label == 0)      count0++;
        else if (label == 1) count1++;
    }

    return (count1 > count0) ? 1 : 0;
}

int main() {
    double train_data[NUM_TRAIN][DIM] = {
        {1.0, 2.0, 1.5},
        {2.0, 1.0, 2.5},
        {0.5, 1.5, 1.0},
        {3.0, 3.5, 2.0},
        {2.5, 2.0, 3.0},
        {3.5, 0.5, 2.5}
    };
    int train_labels[NUM_TRAIN] = {0, 0, 0, 1, 1, 1};

    double query[DIM] = {2.0, 2.0, 2.0};

    int result = knn(train_data, train_labels, NUM_TRAIN, query);

    cout << "Predicted label: " << result << endl;
    return 0;
}

#include <iostream>
using namespace std;

#define ROWS 5
#define COLS 6

void median_filter(const int input[ROWS][COLS], int output[ROWS][COLS], int rows, int cols, int window_size) {
    int half = window_size / 2;
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            int count = 0;
            int* window = new int[window_size * window_size];
            for (int wi = i - half; wi <= i + half; ++wi) {
                for (int wj = j - half; wj <= j + half; ++wj) {
                    if (wi >= 0 && wi < rows && wj >= 0 && wj < cols) {
                        window[count++] = input[wi][wj];
                    }
                }
            }
            for (int x = 0; x < count - 1; ++x) {
                for (int y = x + 1; y < count; ++y) {
                    if (window[x] > window[y]) {
                        int tmp = window[x];
                        window[x] = window[y];
                        window[y] = tmp;
                    }
                }
            }
            output[i][j] = window[count / 2];
            delete[] window;
        }
    }
}

int main() {
    int input[ROWS][COLS] = {
        {10, 20, 30, 40, 50, 60},
        {15, 25, 35, 45, 55, 65},
        {20, 30, 40, 50, 60, 70},
        {25, 35, 45, 55, 65, 75},
        {30, 40, 50, 60, 70, 80}
    };
    int output[ROWS][COLS];
    int window_size = 3;

    median_filter(input, output, ROWS, COLS, window_size);

    for (int i = 0; i < ROWS; ++i) {
        for (int j = 0; j < COLS; ++j) {
            cout << output[i][j] << " ";
        }
        cout << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

void sobelEdgeDetection(const unsigned char* input,
                        unsigned char* output,
                        int width,
                        int height)
{
    int Gx[3][3] = {
        {-1, 0, 1},
        {-2, 0, 2},
        {-1, 0, 1}
    };
    int Gy[3][3] = {
        {-1, -2, -1},
        {0, 0, 0},
        {1, 2, 1}
    };

    for(int x = 0; x < width; x++){
        output[x] = 0;
        output[(height - 1) * width + x] = 0;
    }
    for(int y = 0; y < height; y++){
        output[y * width] = 0;
        output[y * width + (width - 1)] = 0;
    }

    for(int y = 1; y < height - 1; y++){
        for(int x = 1; x < width - 1; x++){
            int sumX = 0;
            int sumY = 0;
            for(int ky = -1; ky <= 1; ky++){
                for(int kx = -1; kx <= 1; kx++){
                    int pixel = input[(y + ky) * width + (x + kx)];
                    sumX += Gx[ky + 1][kx + 1] * pixel;
                    sumY += Gy[ky + 1][kx + 1] * pixel;
                }
            }
            int magnitude = abs(sumX) + abs(sumY);
            if(magnitude > 255) magnitude = 255;
            output[y * width + x] = static_cast<unsigned char>(magnitude);
        }
    }
}

int main()
{
    int width  = 64;
    int height = 64;

    unsigned char* input  = new unsigned char[width * height];
    unsigned char* output = new unsigned char[width * height];

    for(int i = 0; i < width * height; i++){
        input[i] = static_cast<unsigned char>(i % 256);
    }

    sobelEdgeDetection(input, output, width, height);

    for(int i = 0; i < 1000; i++){
        cout << static_cast<int>(output[i]) << " ";
    }
    cout << endl;

    delete[] input;
    delete[] output;
    return 0;
}

#include <iostream>
using namespace std;

void trainSVM(double* X, int* y,
              int n,
              int d,
              double C,
              double lr,
              int epochs,
              double* w,
              double& b) {
    for (int j = 0; j < d; j++) w[j] = 0.0;
    b = 0.0;

    for (int it = 0; it < epochs; it++) {
        for (int i = 0; i < n; i++) {
            double dot = 0.0;
            for (int j = 0; j < d; j++)
                dot += w[j] * X[i * d + j];
            double margin = y[i] * (dot + b);

            if (margin < 1) {
                for (int j = 0; j < d; j++) {
                    w[j] += lr * (C * y[i] * X[i * d + j] - w[j]);
                }
                b += lr * C * y[i];
            } else {
                for (int j = 0; j < d; j++) {
                    w[j] += lr * (-w[j]);
                }
            }
        }
    }
}

int main() {
    const int n = 4, d = 2;
    double X[n * d] = {
        3.0, 3.0,
        4.0, 3.0,
        1.0, 1.0,
        0.0, 2.0
    };
    int y[n] = { 1, 1, -1, -1 };

    double w[d];
    double b;
    double C = 1.0;
    double lr = 0.001;
    int epochs = 1000;

    trainSVM(X, y, n, d, C, lr, epochs, w, b);

    cout << "Weights: ";
    for (int j = 0; j < d; j++)
        cout << w[j] << " ";
    cout << "\nBias: " << b << endl;

    return 0;
}
